package io.github.jesterportfolio.hearth.survival.enchants;

import java.nio.file.*;import java.nio.channels.FileChannel;import java.util.*;import java.util.function.*;
import org.bukkit.configuration.file.YamlConfiguration;
import org.bukkit.plugin.java.JavaPlugin;
import com.google.gson.*;

/** 동일한 YAML 정본의 원자적 reload/CAS 편집. 오류 시 이전 세대와 기존 item ID를 보존한다. */
public final class EnchantCatalog {
    public record Snapshot(long generation,Map<String,EnchantDefinition> definitions){public Snapshot{definitions=Map.copyOf(definitions);}}
    private final Path directory;private final Set<String> effectTypes;private Snapshot current=new Snapshot(0,Map.of());
    public EnchantCatalog(JavaPlugin plugin,Set<String> effects)throws Exception{
        effectTypes=Set.copyOf(effects);directory=plugin.getDataFolder().toPath().toAbsolutePath().resolve("enchants");Files.createDirectories(directory);if(!directory.equals(directory.toRealPath()))throw new IllegalArgumentException("ENCHANT_CONFIG_PATH");
        try(var reader=new java.io.InputStreamReader(Objects.requireNonNull(plugin.getResource("enchants/catalog.json")),java.nio.charset.StandardCharsets.UTF_8)){var json=JsonParser.parseReader(reader).getAsJsonObject();for(var row:json.getAsJsonArray("rows")){String id=row.getAsJsonObject().get("id").getAsString().split(":")[1];Path target=directory.resolve(id+".yml");if(!Files.exists(target,LinkOption.NOFOLLOW_LINKS))try(var in=Objects.requireNonNull(plugin.getResource("enchants/"+id+".yml"))){Files.copy(in,target);}}}
        reload();
    }
    public Snapshot snapshot(){return current;}
    public void reload()throws Exception{var definitions=new LinkedHashMap<String,EnchantDefinition>();try(var files=Files.list(directory)){for(var file:files.sorted().toList()){if(!file.getFileName().toString().endsWith(".yml")||file.getFileName().toString().equals("operations.yml"))continue;if(definitions.size()>=512||!file.equals(file.toRealPath())||Files.size(file)>65536)throw new IllegalArgumentException("ENCHANT_CONFIG_PATH");var yaml=new YamlConfiguration();yaml.load(file.toFile());var def=EnchantDefinition.parse(map(yaml));if(!file.getFileName().toString().equals(def.id().split(":")[1]+".yml")||definitions.put(def.id(),def)!=null)throw new IllegalArgumentException("ENCHANT_DUPLICATE_ID");validate(def);}}for(var d:definitions.values())for(String id:d.conflicts())if(!definitions.containsKey(id))throw new IllegalArgumentException("ENCHANT_CONFLICT_ID");current=new Snapshot(current.generation()+1,definitions);}
    public void edit(String id,long expected,Consumer<YamlConfiguration> edit)throws Exception{if(current.generation()!=expected)throw new IllegalStateException("ENCHANT_CONFIG_STALE");var original=Objects.requireNonNull(current.definitions().get(id));var yaml=new YamlConfiguration();Path file=directory.resolve(id.split(":")[1]+".yml");yaml.load(file.toFile());if(!map(yaml).equals(original.document()))throw new IllegalStateException("ENCHANT_CONFIG_EXTERNAL_CHANGE");edit.accept(yaml);var next=EnchantDefinition.parse(map(yaml));if(!next.id().equals(id))throw new IllegalArgumentException("ENCHANT_ID_IMMUTABLE");validate(next);for(String conflict:next.conflicts())if(!current.definitions().containsKey(conflict))throw new IllegalArgumentException("ENCHANT_CONFLICT_ID");publish(file,yaml,false);var updated=new LinkedHashMap<>(current.definitions());updated.put(id,next);current=new Snapshot(current.generation()+1,updated);}
    public void create(String id,String copyFrom)throws Exception{if(!id.matches("hearth:[a-z][a-z0-9_]{0,48}")||current.definitions().containsKey(id)||current.definitions().size()>=512)throw new IllegalArgumentException("ENCHANT_NEW_ID");var base=Objects.requireNonNull(current.definitions().get(copyFrom));var yaml=new YamlConfiguration();base.document().forEach(yaml::set);yaml.set("id",id);yaml.set("name",id.split(":")[1]);yaml.set("enabled",false);yaml.set("source",null);validate(EnchantDefinition.parse(map(yaml)));publish(directory.resolve(id.split(":")[1]+".yml"),yaml,true);var updated=new LinkedHashMap<>(current.definitions());updated.put(id,EnchantDefinition.parse(map(yaml)));current=new Snapshot(current.generation()+1,updated);}
    private void validate(EnchantDefinition d){if(d.equipment().isEmpty()||d.slots().isEmpty()||!Set.of("armor","helmet","boots","sword","bow","axe","pickaxe","tool","hoe","damaged-items","any").containsAll(d.equipment())||!Set.of("MAIN_HAND","OFF_HAND","HEAD","CHEST","LEGS","FEET").containsAll(d.slots()))throw new IllegalArgumentException("ENCHANT_EQUIPMENT");for(var rule:d.rules())for(var effect:rule.effects()){if(effect.type().equals("summon")&&!Set.of("WOLF","IRON_GOLEM","BEE","ZOMBIE","ENDERMITE","SILVERFISH").contains(effect.arguments().getOrDefault("entity","WOLF")))throw new IllegalArgumentException("ENCHANT_SUMMON_TYPE");if(effect.type().equals("potion")&&org.bukkit.Registry.POTION_EFFECT_TYPE.get(org.bukkit.NamespacedKey.minecraft(effect.arguments().getOrDefault("potion","SPEED").toLowerCase(Locale.ROOT)))==null)throw new IllegalArgumentException("ENCHANT_POTION");if(effect.type().equals("aura_stat")&&rule.trigger()!=EnchantDefinition.Trigger.EQUIP)throw new IllegalArgumentException("ENCHANT_STAT_REQUIRES_EQUIP");if(!effectTypes.contains(effect.type()))throw new IllegalArgumentException("ENCHANT_UNKNOWN_EFFECT_"+effect.type());for(var entry:effect.arguments().entrySet())if(Set.of("amount","duration","radius","bonus","vertical","increment","maximum","expiry","lifetime").contains(entry.getKey()))Formula.of(entry.getValue());}}
    private void publish(Path file,YamlConfiguration yaml,boolean fresh)throws Exception{Path temp=file.resolveSibling(file.getFileName()+".writing");try(var out=Files.newBufferedWriter(temp,StandardOpenOption.CREATE_NEW)){out.write(yaml.saveToString());}try(var c=FileChannel.open(temp,StandardOpenOption.WRITE)){c.force(true);}if(fresh){Files.createLink(file,temp);Files.delete(temp);}else Files.move(temp,file,StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);}
    private static Map<String,Object> map(org.bukkit.configuration.ConfigurationSection section){var result=new LinkedHashMap<String,Object>();for(String key:section.getKeys(false)){Object value=section.get(key);if(value instanceof org.bukkit.configuration.ConfigurationSection nested)value=map(nested);result.put(key,value);}return result;}
}
